 'A': pairs,
 'B': len(pairs).to_bytes(8,'big')+pairs,
 'C': pairs+ (0).to_bytes(8,'big'),
 'D': (1).to_bytes(8,'big')+pairs,
}
for tn,tv in [('t0',0),('t1',1),('t2',2)]:
  for cn,cv in cands.items():
